import json
from datetime import datetime

BOOKS = []
LOANS = []
_next = {"book": 1, "loan": 1}


def _new_id(kind):
    v = _next[kind]
    _next[kind] += 1
    return str(v)


def _now():
    return datetime.now().replace(microsecond=0).isoformat()


def _parse(body):
    if not body:
        return None, (400, {"error": "請提供 JSON 請求內容"})
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return None, (400, {"error": "請求內容不是有效的 JSON"})
    if not isinstance(data, dict):
        return None, (400, {"error": "請求內容必須是 JSON 物件"})
    return data, None


def _str(data, key):
    v = data.get(key)
    if v is None:
        return ""
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        v = str(v)
    if not isinstance(v, str):
        return ""
    return v.strip()


def _find_book(book_id):
    for b in BOOKS:
        if b["id"] == book_id:
            return b
    return None


def _active_loan(book_id):
    for l in LOANS:
        if l["book_id"] == book_id and l["returned_at"] is None:
            return l
    return None


def _list_books():
    return 200, {"items": [dict(b) for b in BOOKS]}


def _add_book(body):
    data, err = _parse(body)
    if err:
        return err
    title = _str(data, "title")
    author = _str(data, "author")
    if not title:
        return 400, {"error": "請輸入書名"}
    if not author:
        return 400, {"error": "請輸入作者"}
    book = {"id": _new_id("book"), "title": title, "author": author, "available": True}
    BOOKS.append(book)
    return 201, dict(book)


def _lend(body):
    data, err = _parse(body)
    if err:
        return err
    book_id = _str(data, "book_id")
    borrower = _str(data, "borrower")
    if not book_id:
        return 400, {"error": "請提供書籍 id"}
    if not borrower:
        return 400, {"error": "請輸入借閱人姓名"}
    book = _find_book(book_id)
    if book is None:
        return 404, {"error": "找不到這本書"}
    if not book["available"] or _active_loan(book_id) is not None:
        return 409, {"error": "書籍已借出"}
    loan = {
        "id": _new_id("loan"),
        "book_id": book_id,
        "borrower": borrower,
        "borrowed_at": _now(),
        "returned_at": None,
    }
    LOANS.append(loan)
    book["available"] = False
    return 201, dict(loan)


def _return(body):
    data, err = _parse(body)
    if err:
        return err
    book_id = _str(data, "book_id")
    if not book_id:
        return 400, {"error": "請提供書籍 id"}
    book = _find_book(book_id)
    if book is None:
        return 404, {"error": "找不到這本書"}
    loan = _active_loan(book_id)
    if loan is None:
        return 409, {"error": "書籍並非借出中"}
    loan["returned_at"] = _now()
    book["available"] = True
    return 200, dict(loan)


def _active():
    items = []
    for l in LOANS:
        if l["returned_at"] is None:
            book = _find_book(l["book_id"])
            items.append({
                "id": l["id"],
                "book_id": l["book_id"],
                "title": book["title"] if book else "",
                "borrower": l["borrower"],
                "borrowed_at": l["borrowed_at"],
            })
    return 200, {"items": items}


ROUTES = {
    "/books": {"GET": lambda b: _list_books(), "POST": _add_book},
    "/loans": {"POST": _lend},
    "/returns": {"POST": _return},
    "/loans/active": {"GET": lambda b: _active()},
}


def handle(method, path, body):
    try:
        p = path.split("?", 1)[0]
        if not p.startswith("/"):
            p = "/" + p
        if len(p) > 1:
            p = p.rstrip("/")
        route = ROUTES.get(p)
        if route is None:
            return 404, {"error": "找不到路徑"}
        fn = route.get(method.upper())
        if fn is None:
            return 405, {"error": "不支援的請求方法"}
        return fn(body)
    except Exception:
        return 500, {"error": "伺服器發生錯誤"}

