(function () {
  "use strict";

  var messageEl = document.getElementById("message");
  var booksBody = document.getElementById("books-body");
  var loansBody = document.getElementById("loans-body");
  var bookForm = document.getElementById("book-form");
  var titleInput = document.getElementById("book-title");
  var authorInput = document.getElementById("book-author");

  var messageTimer = null;

  function showMessage(text, isError) {
    messageEl.textContent = text;
    messageEl.className = "message " + (isError ? "error" : "ok");
    messageEl.hidden = false;
    if (messageTimer) {
      clearTimeout(messageTimer);
      messageTimer = null;
    }
    if (!isError) {
      messageTimer = setTimeout(function () {
        messageEl.hidden = true;
      }, 4000);
    }
  }

  function clearMessage() {
    messageEl.hidden = true;
    messageEl.textContent = "";
  }

  // API 呼叫：封裝回應處理與錯誤訊息
  function handleResponse(res) {
    return res.text().then(function (text) {
      var data = null;
      if (text) {
        try {
          data = JSON.parse(text);
        } catch (e) {
          data = null;
        }
      }
      if (!res.ok) {
        var msg = data && data.error ? data.error : "請求失敗（HTTP " + res.status + "）";
        var err = new Error(msg);
        err.status = res.status;
        throw err;
      }
      if (data === null) {
        throw new Error("伺服器回應格式不正確");
      }
      return data;
    });
  }

  function networkFailure() {
    throw new Error("無法連線到伺服器，請稍後再試");
  }

  function request(fetchPromise) {
    return fetchPromise.then(handleResponse, networkFailure);
  }

  function postOptions(body) {
    return {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body)
    };
  }

  function reportError(err) {
    showMessage(err && err.message ? err.message : "發生未知錯誤", true);
  }

  function cell(text, className) {
    var td = document.createElement("td");
    td.textContent = text;
    if (className) {
      td.className = className;
    }
    return td;
  }

  function emptyRow(colspan, text) {
    var tr = document.createElement("tr");
    var td = document.createElement("td");
    td.colSpan = colspan;
    td.className = "empty";
    td.textContent = text;
    tr.appendChild(td);
    return tr;
  }

  function formatTime(value) {
    if (!value) {
      return "";
    }
    var d = new Date(value);
    if (isNaN(d.getTime())) {
      return String(value);
    }
    return d.toLocaleString("zh-TW");
  }

  // 書籍管理與借閱操作
  function renderBooks(items) {
    booksBody.textContent = "";
    if (!items.length) {
      booksBody.appendChild(emptyRow(4, "目前沒有書籍"));
      return;
    }
    items.forEach(function (book) {
      var tr = document.createElement("tr");
      tr.appendChild(cell(book.title));
      tr.appendChild(cell(book.author));

      var statusTd = document.createElement("td");
      var badge = document.createElement("span");
      badge.className = "badge " + (book.available ? "in" : "out");
      badge.textContent = book.available ? "在館" : "借出中";
      statusTd.appendChild(badge);
      tr.appendChild(statusTd);

      var actionTd = document.createElement("td");
      if (book.available) {
        var form = document.createElement("form");
        form.className = "loan-form";
        form.autocomplete = "off";
        var input = document.createElement("input");
        input.type = "text";
        input.placeholder = "借閱人姓名";
        input.required = true;
        input.setAttribute("aria-label", "借閱人姓名");
        var btn = document.createElement("button");
        btn.type = "submit";
        btn.textContent = "借出";
        form.appendChild(input);
        form.appendChild(btn);
        form.addEventListener("submit", function (ev) {
          ev.preventDefault();
          lendBook(book, input.value.trim(), btn);
        });
        actionTd.appendChild(form);
      } else {
        var returnBtn = document.createElement("button");
        returnBtn.type = "button";
        returnBtn.className = "secondary";
        returnBtn.textContent = "歸還";
        returnBtn.addEventListener("click", function () {
          returnBook(book, returnBtn);
        });
        actionTd.appendChild(returnBtn);
      }
      tr.appendChild(actionTd);
      booksBody.appendChild(tr);
    });
  }

  // 借出中清單
  function renderLoans(items) {
    loansBody.textContent = "";
    if (!items.length) {
      loansBody.appendChild(emptyRow(3, "目前沒有借出中的書籍"));
      return;
    }
    items.forEach(function (loan) {
      var tr = document.createElement("tr");
      tr.appendChild(cell(loan.title));
      tr.appendChild(cell(loan.borrower));
      tr.appendChild(cell(formatTime(loan.borrowed_at)));
      loansBody.appendChild(tr);
    });
  }

  function loadBooks() {
    return request(fetch("api/books")).then(function (data) {
      renderBooks(Array.isArray(data.items) ? data.items : []);
    });
  }

  function loadLoans() {
    return request(fetch("api/loans/active")).then(function (data) {
      renderLoans(Array.isArray(data.items) ? data.items : []);
    });
  }

  function refresh() {
    return Promise.all([loadBooks(), loadLoans()]).catch(reportError);
  }

  function lendBook(book, borrower, btn) {
    if (!borrower) {
      showMessage("請輸入借閱人姓名", true);
      return;
    }
    btn.disabled = true;
    request(fetch("api/loans", postOptions({ book_id: book.id, borrower: borrower })))
      .then(function () {
        showMessage("已將《" + book.title + "》借給 " + borrower, false);
      })
      .catch(reportError)
      .then(function () {
        return refresh();
      });
  }

  function returnBook(book, btn) {
    btn.disabled = true;
    request(fetch("api/returns", postOptions({ book_id: book.id })))
      .then(function () {
        showMessage("已歸還《" + book.title + "》", false);
      })
      .catch(reportError)
      .then(function () {
        return refresh();
      });
  }

  bookForm.addEventListener("submit", function (ev) {
    ev.preventDefault();
    var title = titleInput.value.trim();
    var author = authorInput.value.trim();
    if (!title || !author) {
      showMessage("請填寫書名與作者", true);
      return;
    }
    clearMessage();
    request(fetch("api/books", postOptions({ title: title, author: author })))
      .then(function (book) {
        bookForm.reset();
        showMessage("已新增《" + (book.title || title) + "》", false);
        titleInput.focus();
      })
      .catch(reportError)
      .then(function () {
        return refresh();
      });
  });

  refresh();
})();

