  padding: 8px 10px;
  border: 1px solid #c4cbd2;
  border-radius: 6px;
  font-size: 1rem;
}

button {
  margin-top: 12px;
  padding: 8px 16px;
  border: none;
  border-radius: 6px;
  background: #2563eb;
  color: #fff;
  font-size: 0.95rem;
  cursor: pointer;
}

button:hover {
  background: #1d4fc4;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

button.secondary {
  margin-top: 0;
  background: #6b7280;
}

button.secondary:hover {
  background: #4b5563;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  text-align: left;
  padding: 8px 6px;
  border-bottom: 1px solid #e5e8eb;
  vertical-align: middle;
}

th {
  font-size: 0.85rem;
  color: #555;
}

td.empty {
  text-align: center;
  color: #888;
  padding: 16px;
}

.badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 0.85rem;
}

.badge.in {
  background: #e8f5e9;
  color: #1e6b2e;
}

.badge.out {
  background: #fff3e0;
  color: #b45309;
}

.loan-form {
  display: flex;
  gap: 8px;
  align-items: center;
}

.loan-form input[type="text"] {
  max-width: 180px;
  padding: 6px 8px;
}

.loan-form button {
  margin-top: 0;
  padding: 6px 14px;
}
